//! Suhina's own `config.h` for the vendored LAME 3.100 encoder. Upstream's is generated by
//! autotools, and `configMS.h` is MSVC-only, so neither is shipped; this file is what
//! `HAVE_CONFIG_H` finds. It says a plain portable C environment and nothing more: no NASM
//! assembly (`HAVE_NASM`), no bundled decoder (`HAVE_MPGLIB` — Symphonia decodes).

#ifndef SUHINA_LAME_CONFIG_H
#define SUHINA_LAME_CONFIG_H

#define STDC_HEADERS 1
#define HAVE_STDINT_H 1
#define HAVE_INTTYPES_H 1
#define HAVE_LIMITS_H 1
#define HAVE_ERRNO_H 1
#define HAVE_FCNTL_H 1
#define HAVE_STRCHR 1
#define HAVE_MEMCPY 1

#define PACKAGE "lame"
#define VERSION "3.100"

/* configure would probe for this C type; every compiler we build with has `float`. */
typedef float ieee754_float32_t;

#endif
